function generateSummaryStats(allResults, comparison) {
    let totalTests = 0;
    let totalCategories = 0;
    
    allResults.forEach(category => {
        totalCategories++;
        if (category.tests) {
            totalTests += category.tests.length;
        }
    });
    
    let comparedTests = 0;
    if (comparison && comparison.summary) {
        comparedTests = comparison.summary.compared || 0;
    }
    
    return `
        <div class="summary-item">
            <h4>Total Categories</h4>
            <div class="value">${totalCategories}</div>
        </div>
        <div class="summary-item">
            <h4>Total Tests</h4>
            <div class="value">${totalTests}</div>
        </div>
        ${comparedTests > 0 ? `
        <div class="summary-item">
            <h4>Compared Tests</h4>
            <div class="value">${comparedTests}</div>
        </div>
        ` : ''}
    `;
}

function generateCategorySections(allResults, comparison) {
    let html = '';
    
    allResults.forEach(category => {
        html += `
        <div class="section">
            <h2>${category.category}</h2>
            ${generateTestTable(category, comparison)}
            ${generateCategoryChart(category, comparison)}
        </div>
        `;
    });
    
    return html;
}

function generateTestTable(category, comparison) {
    if (!category.tests || category.tests.length === 0) {
        return '<p>No tests available for this category.</p>';
    }
    
    // Create comparison map
    const comparisonMap = {};
    if (comparison && comparison.tests) {
        comparison.tests.forEach(test => {
            if (test && test.category === category.category) {
                comparisonMap[test.name] = test;
            }
        });
    }
    
    let tableHtml = `
    <table>
        <thead>
            <tr>
                <th>Test Name</th>
                <th>Mean (ms)</th>
                <th>Median (ms)</th>
                <th>Min (ms)</th>
                <th>Max (ms)</th>
                <th>Std Dev (ms)</th>
                ${comparison ? '<th>Comparison</th>' : ''}
            </tr>
        </thead>
        <tbody>
    `;
    
    category.tests.forEach((test, i) => {
        const comp = test ? comparisonMap[test.name] : undefined;
        let comparisonCell = '';
        
        if (comp && comp.comparison) {
            const { ratio, percentDiff, faster } = comp.comparison;
            const badgeClass = faster === 'protojs' ? 'badge-success' : 
                             Math.abs(percentDiff) < 10 ? 'badge-warning' : 'badge-danger';
            const badgeText = faster === 'protojs' ? 'Faster' : 
                            Math.abs(percentDiff) < 10 ? 'Similar' : 'Slower';
            comparisonCell = `
                <td>
                    <span class="badge ${badgeClass}">${badgeText}</span><br>
                    <small>${percentDiff > 0 ? '+' : ''}${Math.round(percentDiff * 10) / 10}%</small>
                </td>
            `;
        } else if (comparison) {
            comparisonCell = '<td>-</td>';
        }
        
        
        tableHtml += `
            <tr>
                <td>${test ? test.name : 'Unknown'}</td>
                <td>${test && test.mean !== undefined ? String(Number(test.mean)) : '0'}</td>
                <td>${test && test.median !== undefined ? String(Number(test.median)) : '0'}</td>
                <td>${test && test.min !== undefined ? String(Number(test.min)) : '0'}</td>
                <td>${test && test.max !== undefined ? String(Number(test.max)) : '0'}</td>
                <td>${test && test.stddev !== undefined ? String(Number(test.stddev)) : '0'}</td>
                ${comparisonCell}
            </tr>
        `;
    });
    
    tableHtml += `
        </tbody>
    </table>
    `;
    
    return tableHtml;
}

function generateCategoryChart(category, comparison) {
    if (!category.tests || category.tests.length === 0) {
        return '';
    }
    
    const chartId = `chart-${category.category.replace(' ', '-').toLowerCase()}`;
    const labels = category.tests.map(t => t ? t.name : 'Unknown');
    const protojsData = category.tests.map(t => t ? Number(t.mean) : 0);
    
    let nodejsData = null;
    if (comparison && comparison.tests) {
        const comparisonMap = {};
        comparison.tests.forEach(test => {
            if (test && test.category === category.category && test.nodejs) {
                comparisonMap[test.name] = test.nodejs.mean;
            }
        });
        nodejsData = category.tests.map(t => t ? (comparisonMap[t.name] || null) : null);
    }
    
    const datasets = [{
        label: 'ProtoJS',
        data: protojsData,
        backgroundColor: 'rgba(52, 152, 219, 0.6)',
        borderColor: 'rgba(52, 152, 219, 1)',
        borderWidth: 1
    }];
    
    if (nodejsData && nodejsData.some(v => v !== null)) {
        datasets.push({
            label: 'Node.js',
            data: nodejsData,
            backgroundColor: 'rgba(46, 204, 113, 0.6)',
            borderColor: 'rgba(46, 204, 113, 1)',
            borderWidth: 1
        });
    }
    
    return `
    <div class="chart-container">
        <h3>Performance Comparison Chart</h3>
        <canvas id="${chartId}" width="400" height="200"></canvas>
        <script>
            (function() {
                const ctx = document.getElementById('${chartId}').getContext('2d');
                new Chart(ctx, {
                    type: 'bar',
                    data: {
                        labels: ${JSON.stringify(labels)},
                        datasets: ${JSON.stringify(datasets)}
                    },
                    options: {
                        responsive: true,
                        scales: {
                            y: {
                                beginAtZero: true,
                                title: {
                                    display: true,
                                    text: 'Time (ms)'
                                }
                            }
                        }
                    }
                });
            })();
        </script>
    </div>
    `;
}

function generateChartScripts(allResults, comparison) {
    // Charts are generated inline in generateCategoryChart
    return '';
}

function getEnvironmentInfo() {
    let info = [];
    
    if (typeof process !== 'undefined') {
        if (process.platform) info.push(`Platform: ${process.platform}`);
        if (process.arch) info.push(`Architecture: ${process.arch}`);
    }
    
    return info.length > 0 ? info.join(', ') : 'Unknown';
}

